// 关卡 03 · 非零退出是一次观察,不是一次异常
//
// runBash 只有十行,里面有三个决定会一路影响 agent 的行为。
// 真实的 stage 00 在这里调用 exec.Command(shell, "-c", command);
// 这一关把执行换成 fakeExec,好让你只盯着返回值的形状。
package main

import (
	"fmt"
	"strings"
)

// runBash 跑一条命令,返回模型应该看到的东西。
func runBash(command string) string {
	res := fakeExec(command)

	// 模型该看到哪几股输出
	result := [[1]]

	if res.Err != nil {
		// 命令以非零退出收场了
		[[2]]
	}

	if strings.TrimSpace(result) == "" {
		[[3]]
	}

	return result
}

func main() {
	for _, cmd := range []string{
		"ls",
		"mkdir -p out",
		"grep tool_call_id README.md",
		"python stats.py",
	} {
		fmt.Printf("$ %s\n%s\n\n", cmd, indent(runBash(cmd)))
	}
}

package main

import (
	"errors"
	"strings"
)

// result 是 fakeExec 的返回值。真实代码里 cmd.CombinedOutput() 一次就把
// 两股输出拼好了;这里把它们分开,好让第一个决定真的成为一个决定。
type result struct {
	Stdout string
	Stderr string
	Err    error
}

func fakeExec(command string) result {
	switch command {
	case "ls":
		return result{Stdout: "README.md\nmain.go\nstats.py\n"}
	case "mkdir -p out":
		// 成功,而且一个字都不打印。这种命令比你以为的多。
		return result{}
	case "grep tool_call_id README.md":
		// grep 没找到东西的时候退出码是 1,并且什么都不输出。
		return result{Err: errors.New("exit status 1")}
	case "python stats.py":
		return result{
			Stderr: "Traceback (most recent call last):\n" +
				"  File \"stats.py\", line 7, in <module>\n" +
				"    print(total / len(rows))\n" +
				"ZeroDivisionError: division by zero\n",
			Err: errors.New("exit status 1"),
		}
	}
	return result{Err: errors.New("exit status 127")}
}

func indent(s string) string {
	s = strings.TrimRight(s, "\n")
	return "  | " + strings.ReplaceAll(s, "\n", "\n  | ")
}
